 $copy=$p;$copy['slug']='premium';$copy['price_monthly']='29.90';unset($copy['external_id']);$new=$service->savePlan($system,null,$copy,null,1,'Novo plano');
 verify($new!==$id&&strlen($new)===36,'new central plan has stable UUID');
 $service->saveAccount($system,$account,$new,true,2,1,'Reativação com novo plano');$next=$call($payload);
