 $invalid=$copy;$invalid['limits']['vehicles']=-5;reject(fn()=>$service->savePlan($system,$new,$invalid,1,1,'invalid'),422,'invalid negative limit rejected');
 $invalid=$copy;$invalid['price_monthly']='-1';reject(fn()=>$service->savePlan($system,$new,$invalid,1,1,'invalid'),422,'invalid price rejected');
 reject(fn()=>$service->savePlan($system,null,$copy,null,1,'duplicate'),409,'duplicate slug rejected without overwrite');
 $community=$p;$community['slug']='community';$community['price_monthly']='5';unset($community['external_id']);reject(fn()=>$service->savePlan($system,null,$community,null,1,'paid'),422,'free signup plan protected');
 $community['price_monthly']='0';$community['active']=false;reject(fn()=>$service->savePlan($system,null,$community,null,1,'inactive'),422,'signup plan cannot be disabled');
 $failure=$ack;$failure['plans'][0]['revision']=2;$failure['plans'][0]['ok']=false;$call($failure);
 verify($db->query('select sync_error from plans where external_id='.$db->quote($id))->fetchColumn()===null,'old failed ack cannot obscure success');
 $changed['name']='Terceira';$service->savePlan($system,$id,$changed,2,1,'Terceira revisão');$failure['plans'][0]['revision']=3;$call($failure);
 verify($db->query('select sync_error from plans where external_id='.$db->quote($id))->fetchColumn()!==null,'application failure visible');
