 $db->exec("update vendors set commission_installments=3 where code='ANA-01'");
 $sold=$payload;$sold['accounts']=[array_replace($a,['external_id'=>'00000000-0000-4000-8000-000000000031','slug'=>'qa-31','vendor_code'=>'ana-01']),array_replace($a,['external_id'=>'00000000-0000-4000-8000-000000000032','slug'=>'qa-32'])];
 $call($sold);$call($sold);
 $owner=fn($id)=>$db->query("select v.code,va.commission_type,va.installments_limit,va.source from vendor_assignments va join vendors v on v.id=va.vendor_id where va.ends_at is null and va.tenant_external_id=".$db->quote($id))->fetchAll();
